#include <linux/mm.h>
#include <linux/printk.h>
#include <linux/atomic.h>

#define dprintk(level, fmt, args...) \
    do { \
        if (current_debug_level >= level) \
            printk(KERN_DEBUG "vbuf-sg: " fmt, ##args); \
    } while (0)

struct videobuf_mapping {
    atomic_t ref;
};

int videobuf_vm_open(struct vm_area_struct *vma)
{
    struct videobuf_mapping *mapping = vma->vm_private_data;

    dprintk(1, "open: mapping %p, refcount %d\n",
            mapping, atomic_read(&mapping->ref));
    atomic_inc(&mapping->ref);

    return 0;
}

