#include <linux/printk.h>
#include <linux/vmalloc.h>
#include <linux/atomic.h>

#define dprintk(level, fmt, args...) \
  do { if (level <= current_debug_level) \
       printk("vbuf-sg: " fmt, ##args); } while (0)

struct videobuf_mapping {
  atomic_t ref_count;
  // ... other fields ...
};

void videobuf_vm_open(struct vm_area_struct *vma) {
  struct videobuf_mapping *mapping = vma->vm_private_data;

  if (!mapping) {
    return;
  }

  dprintk(1, "Opening vma, mapping at %p, ref count %d\n",
          mapping, atomic_read(&mapping->ref_count));

  atomic_inc(&mapping->ref_count);
}

#include <linux/module.h>
#include <linux/printk.h>
#include <linux/vmalloc.h>
#include <linux/kref.h>

#define dprintk(fmt, ...) printk(KERN_DEBUG "vbuf-sg: " fmt, ##__VA_ARGS__)

struct videobuf_mapping {
    struct kref ref;
    // Additional fields would be defined here in the actual context.
};

int videobuf_vm_open(struct vm_area_struct *vma)
{
    struct videobuf_mapping *mapping = vma->vm_private_data;

    dprintk("open (0x%p, ref=%d)\n", mapping, kref_read(&mapping->ref));
    kref_get(&mapping->ref);

    return 0;
}
